            return False
        if name in pins and version != pins[name]:
            return False
        return all(low <= version <= high for low, high in limits)

    def options(name, limits):
        rows = [row for row in packages.get(name, ())
                if allowed(name, row["version"], limits)]
        return sorted(rows, key=lambda row: row["version"], reverse=True)

    best_versions = None
    best_score = None

    def search(limits, selected, graph):
        nonlocal best_versions, best_score

