                upper.append(selected[name]["version"])
                continue
            choices = options(name, limits.get(name, ()))
            if name in limits:
                if not choices:
                    return
                upper.append(choices[0]["version"])
            else:
                upper.append(max([-1] + [row["version"] for row in choices]))
        upper = tuple(upper)
